def bfs(tree, start):
    queue = deque([start])
    visited = set([start])
    parent = {start: None}

    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                queue.append(neighbor)

    return parent

def find_min_companies(n, k, edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Find a root of the tree
    root = 0
    parent = bfs(tree, root)

    # Function to count bad nodes for a given number of companies
    def count_bad_nodes(companies):
        bad_nodes = set()
        for node in range(n):
            if node == root:
                continue
            path = []
            current = node
            while current is not None:
                path.append(current)
                current = parent[current]

            color_count = defaultdict(int)
            for node in path:
                color_count[node] += 1

            for node in path:
                if color_count[node] > companies:
                    bad_nodes.add(node)

        return len(bad_nodes)

    # Binary search for the minimum number of companies
    left, right = 1, n - 1
    while left < right:
        mid = (left + right) // 2
        if count_bad_nodes(mid) <= k:
            right = mid
        else:
            left = mid + 1

    return left

