    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    root = 0
    parent = bfs(tree, root)

    companies = [0] * (n - 1)
    color = 1
    for i, (u, v) in enumerate(edges):
        if parent[u] == v:
            u, v = v, u

        if color > min_companies:
            color = 1

        companies[i] = color
        color += 1

    return companies

